={{ (() => {
  const e = $json;
  const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

  const ABERTURA = {
    evento: '📅 Agendado',
    tarefa: '✅ Anotei a tarefa',
    nota:   '📝 Guardei a nota',
    ideia:  '💡 Registrei a ideia'
  };

  const linhas = [];
  if (e.origem === 'audio') linhas.push(`🎙 <i>Ouvi:</i> ${esc(e.conteudo ?? e.titulo)}`, '');
  linhas.push(`${ABERTURA[e.tipo] ?? '📝 Guardei'} <b>#${e.numero}</b>`);
  linhas.push(esc(e.titulo));

  if (e.inicio) {
    const q = new Date(e.inicio).toLocaleString('pt-BR', { timeZone:'America/Sao_Paulo', dateStyle:'short', timeStyle:'short' });
    linhas.push(`🕐 ${q}`);
  }
  linhas.push(`🏷 ${esc(e.categoria)} · ${esc(e.prioridade)}`);

  if (!e.ia_processado) {
    linhas.push('', `❓ Não tive certeza do que era. Está na fila de espera — corrija com <code>/tipo ${e.numero} tarefa</code> (ou evento, nota, ideia).`);
  }
  return linhas.join('\n');
})() }}

