// A transcrição entra no lugar do texto e segue pelo MESMO caminho da Fase 7.
const entrada = $('Normalizar Entrada').first().json;
const transcricao = ($input.first().json.text ?? '').trim();

return [{
  json: {
    ...entrada,
    texto: transcricao,
    argumento: transcricao,
    comando: '',            // áudio nunca é comando
    transcricao,            // guardado para ecoar na resposta
  },
}];

// Saudação pelo horário de Brasília. O menu é a tela inicial do bot:
// toda mensagem sem contexto ativo termina aqui.
const base = $('Normalizar Entrada').first().json;

const hora = Number(
  new Date().toLocaleString('pt-BR', {
    timeZone: 'America/Sao_Paulo',
    hour: '2-digit',
    hour12: false,
  }),
);

let saudacao;
if (hora < 5)       saudacao = 'Boa madrugada';
else if (hora < 12) saudacao = 'Bom dia';
else if (hora < 18) saudacao = 'Boa tarde';
else                saudacao = 'Boa noite';

const mensagem = [
  `${saudacao}, <b>${base.first_name_safe}</b>`,
  '',
  'O que você quer fazer?',
].join('\n');

return [{ json: { chat_id: base.chat_id, mensagem } }];

