={{ (() => {
  const r = $('Decidir Rota').first().json;
  const u = $('Buscar Usuário').first().json;
  const ctx = r.contextoNovo ?? u.contexto ?? '';

  // Editar um item específico: o alvo já está decidido, falta só a data.
  if (ctx.startsWith('item:edit:')) {
    return `✏️ <b>Nova data para a ${ctx.split(':')[2]}</b>\n\nFala ou escreve quando — <i>"sexta às 15h"</i>, <i>"amanhã de manhã"</i>.`;
  }

  const TEXTOS = {
    'add:tarefa': '📌 <b>Nova tarefa</b>\n\nManda um áudio ou escreve o que precisa fazer.\n<i>Se tiver prazo, fala junto — "pagar a luz sexta às 9h".</i>',
    'add:evento': '📅 <b>Novo evento</b>\n\nManda um áudio ou escreve.\n<i>Diga o dia e a hora — "reunião com o time amanhã às 14h".</i>',
    'add:nota':   '📝 <b>Nova anotação</b>\n\nManda um áudio ou escreve. Guardo exatamente como você disser.',
    'add:ideia':  '💡 <b>Nova ideia</b>\n\nManda um áudio ou escreve.'
  };
  const corpo = TEXTOS[ctx] ?? '📝 Manda um áudio ou escreve o que quer guardar.';

  if (r.rota === 'curto') {
    return `🤔 <b>Muito curto.</b> Preciso de pelo menos 10 caracteres.\n\n${corpo}`;
  }
  if (r.rota === 'longo') {
    return `✂️ <b>Longo demais.</b> Aqui cabem até <b>${r.maxTexto} caracteres</b> — você mandou ${(r.texto ?? '').length}.\n\nResume em uma frase, ou guarda como <b>Anotação</b>, que aceita bem mais.\n\n${corpo}`;
  }
  return corpo;
})() }}

