// Valida a saída do LLM. O tipo NÃO é decidido aqui: veio do botão.
const entrada  = $('Montar Prompt').first().json;
const resposta = $input.first().json;

const CATEGORIAS = ['trabalho', 'pessoal', 'estudos', 'saude', 'financeiro', 'casa', 'outros'];
const PRIORIDADES = ['baixa', 'media', 'alta', 'urgente'];
const TZ = 'America/Sao_Paulo';

// O modelo às vezes devolve a PALAVRA "null" em vez do valor null.
const corta = (v, max) => {
  if (typeof v !== 'string') return null;
  const t = v.trim();
  if (!t || t.toLowerCase() === 'null' || t.toLowerCase() === 'undefined') return null;
  return t.slice(0, max);
};

const dataValida = (v) => {
  if (typeof v !== 'string') return null;
  const d = new Date(v);
  return isNaN(d.getTime()) ? null : d;
};

let bruto = {};
try {
  bruto = JSON.parse(resposta.choices?.[0]?.message?.content ?? '{}');
} catch (e) {
  bruto = {};
}

const confianca = typeof bruto.confianca === 'number'
  ? Math.min(Math.max(bruto.confianca, 0), 1)
  : 0;

const categoria  = CATEGORIAS.includes(bruto.categoria) ? bruto.categoria : 'outros';
const prioridade = PRIORIDADES.includes(bruto.prioridade) ? bruto.prioridade : 'media';

const MAX_TITULO = { tarefa: 60, evento: 50, nota: 200, ideia: 200 };
const limite = MAX_TITULO[entrada.tipo] ?? 200;
const titulo = corta(bruto.titulo, limite) ?? corta(entrada.texto, limite) ?? 'Sem título';
const conteudo = corta(entrada.texto, 4000);

let inicio = bruto.tem_data === true ? dataValida(bruto.inicio) : null;
let fim    = inicio ? dataValida(bruto.fim) : null;
if (inicio && (!fim || fim <= inicio)) fim = new Date(inicio.getTime() + 3600000); // +1h

// O tipo é contrato do botão. Evento sem data é o único caso que cede.
let tipo = entrada.tipo;
if (tipo === 'evento' && !inicio) tipo = 'tarefa';   // CHECK entries_evento_tem_inicio

const hoje = new Date().toLocaleDateString('sv-SE', { timeZone: TZ });
const diaDoInicio = inicio ? inicio.toLocaleDateString('sv-SE', { timeZone: TZ }) : null;

let coluna;
if (tipo === 'nota' || tipo === 'ideia') coluna = 'fila_espera';
else if (diaDoInicio === hoje) coluna = 'fazer_hoje';
else if (inicio) coluna = 'com_prazo';
else coluna = 'sem_prazo';

return [{
  json: {
    ...entrada,
    tipo, titulo, conteudo, categoria, prioridade, coluna,
    inicio: inicio ? inicio.toISOString() : null,
    fim: fim ? fim.toISOString() : null,
    origem: entrada.origem ?? 'texto',
    ia_processado: confianca >= 0.6,
    ia_confianca: confianca,
  },
}];

// ===================================================================
// Decidir Rota — ÚNICO ponto de decisão do bot.
// Traduz clique e mensagem para o mesmo vocabulário de rotas.
// Na Fase 12 este arquivo vira rules.py, com pytest.
// ===================================================================

const MIN_CARACTERES = 10;

// Teto por tipo: tarefa e evento são rótulos curtos, anotação guarda texto.
// O título gravado ainda respeita o CHECK de 200 do banco.
const MAX_CARACTERES = { tarefa: 60, evento: 50, nota: 500, ideia: 500 };
const MAX_TITULO = 200;

const TIPOS = ['tarefa', 'evento', 'nota', 'ideia'];

const base = $('Normalizar Entrada').first().json;
const usuario = $('Buscar Usuário').first().json;
const doFluxo = $input.first().json;

const callback = String(base.callback ?? '');

// -------------------------------------------------------------------
// Extração de números — o alvo pode vir digitado ou falado.
// O Whisper pontua ("27.") e às vezes escreve por extenso.
// -------------------------------------------------------------------
const UNIDADE = {
  zero: 0, um: 1, uma: 1, dois: 2, duas: 2, tres: 3, quatro: 4, cinco: 5,
  seis: 6, sete: 7, oito: 8, nove: 9, dez: 10, onze: 11, doze: 12, treze: 13,
  catorze: 14, quatorze: 14, quinze: 15, dezesseis: 16, dezessete: 17,
  dezoito: 18, dezenove: 19,
};
const DEZENA = {
  vinte: 20, trinta: 30, quarenta: 40, cinquenta: 50,
  sessenta: 60, setenta: 70, oitenta: 80, noventa: 90,
};

const extrairNumeros = (frase) => {
  // normalize('NFD') separa o acento da letra; o replace tira só os acentos.
  const tokens = String(frase ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[.,;:!?]/g, ' ')
    .split(/\s+/)
    .filter(Boolean);

  const achados = [];

  for (let i = 0; i < tokens.length; i++) {
    const t = tokens[i];

    // Dígito puro, com ou sem pontuação já removida
    if (/^[0-9]{1,6}$/.test(t)) {
      achados.push(Number(t));
      continue;
    }

    // "vinte e sete" → 27 ; "vinte" sozinho → 20
    if (DEZENA[t] !== undefined) {
      if (tokens[i + 1] === 'e' && UNIDADE[tokens[i + 2]] !== undefined) {
        achados.push(DEZENA[t] + UNIDADE[tokens[i + 2]]);
        i += 2;
      } else {
        achados.push(DEZENA[t]);
      }
      continue;
    }

    if (UNIDADE[t] !== undefined) achados.push(UNIDADE[t]);
  }

  return [...new Set(achados.filter((n) => n > 0))];
};

// -------------------------------------------------------------------
// CLIQUE — o alvo já veio no botão. Nenhuma interpretação necessária.
// -------------------------------------------------------------------
if (base.origem_evento === 'clique') {
  const TELAS = {
    menu: 'tela_menu',
    hoje: 'agenda',
    listar: 'tela_listas',
    painel: 'tela_config',
    vincular: 'vincular',
  };
  if (TELAS[callback]) return [{ json: { ...base, rota: TELAS[callback] } }];

  const p = callback.split(':');

  // item:concl:25 — age direto, sem perguntar
  if (p[0] === 'item') {
    const numero = Number(p[2]);
    if (p[1] === 'concl' && numero) {
      return [{ json: { ...base, rota: 'concluir', numeros: [numero], numerosCsv: String(numero) } }];
    }
    if (p[1] === 'rem' && numero) {
      return [{ json: { ...base, rota: 'remover', numeros: [numero], numerosCsv: String(numero) } }];
    }
    if (p[1] === 'edit' && numero) {
      // Alvo fixado: falta só a data. O contexto guarda o número.
      return [{ json: { ...base, rota: 'pedir_conteudo', contextoNovo: callback, numeroAlvo: numero } }];
    }
  }

  // list:tarefa — só leitura
  if (p[0] === 'list' && TIPOS.includes(p[1])) {
    return [{ json: { ...base, rota: 'listar_tipo', tipo: p[1] } }];
  }

  // add:tarefa pede conteúdo; concl|rem|edit:tarefa pergunta qual
  if (['add', 'concl', 'rem', 'edit'].includes(p[0]) && TIPOS.includes(p[1])) {
    return [{
      json: {
        ...base,
        rota: p[0] === 'add' ? 'pedir_conteudo' : 'escolher_alvo',
        tipo: p[1],
        contextoNovo: callback,
      },
    }];
  }

  return [{ json: { ...base, rota: 'tela_menu' } }];
}

// -------------------------------------------------------------------
// MENSAGEM — só chega aqui com contexto vivo. O contexto diz a ação.
// -------------------------------------------------------------------
// Áudio já transcrito vem no item; texto digitado vem do Normalizar.
const texto = (doFluxo.texto ?? '').trim() || (base.texto ?? '').trim();

// Os números saem do texto RESOLVIDO, nunca do Normalizar:
// num áudio o Normalizar não tem texto nenhum para analisar.
const numeros = extrairNumeros(texto);

// Dois formatos de contexto:
//   'add:tarefa'    → espera conteúdo, tipo conhecido
//   'item:edit:25'  → espera só a nova data, alvo já fixado
let ctx = String(usuario.contexto ?? '').split(':');
const numeroAlvo = ctx[0] === 'item' ? Number(ctx[2]) : null;
if (numeroAlvo) ctx = [ctx[1], null];

const [acaoCtx, tipoCtx] = ctx;

// nota e ideia não têm data: gravar a transcrição basta, sem LLM.
const precisaDeIA = tipoCtx === 'tarefa' || tipoCtx === 'evento';
const maxTexto = MAX_CARACTERES[tipoCtx] ?? 500;

let rota;
if (acaoCtx === 'add') {
  // O contexto diz o que é, mas não garante que veio conteúdo utilizável.
  if (texto.length < MIN_CARACTERES) rota = 'curto';
  else if (texto.length > maxTexto) rota = 'longo';
  else rota = precisaDeIA ? 'criar_ia' : 'criar_simples';
} else if (acaoCtx === 'concl') rota = 'concluir';
else if (acaoCtx === 'rem')     rota = 'remover';
else if (acaoCtx === 'edit')    rota = 'reagendar';
else                            rota = 'tela_menu';

return [{
  json: {
    ...base,
    texto,
    rota,
    numeros,
    numerosCsv: numeros.join(','),
    numeroAlvo: numeroAlvo ?? numeros[0] ?? null,
    maxTexto,
    tipo: tipoCtx || null,
    coluna: tipoCtx === 'nota' || tipoCtx === 'ideia' ? 'fila_espera' : 'sem_prazo',
    titulo: texto.slice(0, Math.min(maxTexto, MAX_TITULO)) || 'Sem título',
    conteudo: texto || null,
    categoria: 'outros',
    prioridade: 'media',
    inicio: null,
    fim: null,
    ia_processado: !precisaDeIA,
    ia_confianca: null,
  },
}];
